def _split_fields(text):
    """Split text on unquoted SEP characters, honouring doubled quotes."""
    fields = []
    current = []
    quoted = False
    i = 0
    while i < len(text):
        ch = text[i]
        if quoted:
            if ch == QUOTE:
                if i + 1 < len(text) and text[i + 1] == QUOTE:
                    current.append(QUOTE)
