            fields.append("".join(current))
            current = []
            i += 1
        elif ch == QUOTE:
            quoted = True
            current.append(ch)
            i += 1
        else:
            current.append(ch)
            i += 1
    if quoted:
        raise ValueError("unclosed quote")
    fields.append("".join(current))
    return fields


def _find_unquoted(text, target):
    """Index of the first target character outside quotes, or None."""
    quoted = False
    i = 0
    while i < len(text):
        ch = text[i]
        if quoted:
            if ch == QUOTE:
                if i + 1 < len(text) and text[i + 1] == QUOTE:
                    i += 2
                    continue
                quoted = False
            i += 1
        elif ch == QUOTE:
            quoted = True
            i += 1
        elif ch == target:
            return i
        else:
            i += 1
    return None


def _parse_value(text):
    """Turn a stripped field value into its string value."""
    if not text.startswith(QUOTE):
        return text
    out = []
    i = 1
    closed = False
    while i < len(text):
        ch = text[i]
        if ch == QUOTE:
            if i + 1 < len(text) and text[i + 1] == QUOTE:
                out.append(QUOTE)
                i += 2
                continue
            closed = True
            i += 1
            break
        out.append(ch)
        i += 1
    if not closed:
        raise ValueError("unclosed quote")
    if text[i:].strip():
        raise ValueError(f"text after closing quote: {text!r}")
    return "".join(out)


def parse_fields(text):
    """Parse a line like name=Ann| note="hi| there" into a dict of strings.

    Fields are separated by SEP. Whitespace around keys and around unquoted values is
    ignored. A value may be wrapped in QUOTE characters; inside quotes, SEP and '='
    are ordinary characters, whitespace is kept, and two QUOTE characters in a row
    stand for one QUOTE character. Empty fields, such as one after a trailing SEP,
    are skipped, so a blank line gives {}. A field without '=', an empty key, a
    quote that is never closed, or a key that appears twice raises ValueError.
    """
    result = {}
    for field in _split_fields(text):
        if not field.strip():
            continue
        equals = _find_unquoted(field, "=")
        if equals is None:
            raise ValueError(f"field without '=': {field!r}")
        key = field[:equals].strip()
        if not key:
            raise ValueError(f"empty key in {field!r}")
        value = _parse_value(field[equals + 1 :].strip())
        if key in result:
            raise ValueError(f"duplicate key: {key!r}")
        result[key] = value
    return result

