"""Cron-style schedules. SCHEDULE.md has the full rules."""

import calendar
import datetime as dt
import re
from bisect import bisect_left

_NUMBER = re.compile(r"[0-9]+")
_SPLIT = re.compile(r"[ \t]+")

_MONTH_NAMES = {
    "JAN": 1,
    "FEB": 2,
    "MAR": 3,
    "APR": 4,
    "MAY": 5,
    "JUN": 6,
    "JUL": 7,
    "AUG": 8,
    "SEP": 9,
    "OCT": 10,
    "NOV": 11,
    "DEC": 12,
}

_DAY_NAMES = {
    "SUN": 0,
    "MON": 1,
    "TUE": 2,
    "WED": 3,
    "THU": 4,
    "FRI": 5,
    "SAT": 6,
}

_SHORTCUTS = {
    "@yearly": "0 0 1 1 *",
    "@annually": "0 0 1 1 *",
    "@monthly": "0 0 1 * *",
    "@weekly": "0 0 * * 0",
    "@daily": "0 0 * * *",
    "@midnight": "0 0 * * *",
    "@hourly": "0 * * * *",
}


class _Schedule:
    __slots__ = (
        "minutes",
        "hours",
        "months",
        "days",
        "weekdays",
        "last_day",
        "last_weekdays",
        "nth_weekdays",
    )

    def __init__(
        self,
        minutes,
        hours,
        months,
        days,
        weekdays,
        last_day,
        last_weekdays,
        nth_weekdays,
    ):
        self.minutes = minutes
        self.hours = hours
        self.months = months
        self.days = days
        self.weekdays = weekdays
        self.last_day = last_day
        self.last_weekdays = last_weekdays
        self.nth_weekdays = nth_weekdays


def _parse_value(token, names, low, high):
    if _NUMBER.fullmatch(token):
        value = int(token)
    elif names is not None and token.upper() in names:
        value = names[token.upper()]
    else:
        raise ValueError(f"bad value: {token!r}")
    if not low <= value <= high:
        raise ValueError(f"value out of range: {token!r}")
    return value


def _parse_field(text, kind):
    if kind == "minute":
        low, high, names, allow_last, allow_dow_special = 0, 59, None, False, False
    elif kind == "hour":
        low, high, names, allow_last, allow_dow_special = 0, 23, None, False, False
    elif kind == "dom":
        low, high, names, allow_last, allow_dow_special = 1, 31, None, True, False
    elif kind == "month":
        low, high, names, allow_last, allow_dow_special = 1, 12, _MONTH_NAMES, False, False
    else:
        low, high, names, allow_last, allow_dow_special = 0, 7, _DAY_NAMES, False, True

    if text == "?":
        if kind not in ("dom", "dow"):
            raise ValueError("'?' is only allowed in the day fields")
        text = "*"
    if "?" in text:
        raise ValueError("'?' must be the whole field")

    values = set()
    last_day = False
    last_weekdays = set()
    nth_weekdays = set()

    for item in text.split(","):
        if item == "":
            raise ValueError("empty item")

        if allow_last and item == "L":
            last_day = True
            continue

        if allow_dow_special:
            if item == "L":
                raise ValueError("L is not allowed here")
            if item.endswith("L"):
                prefix = item[:-1]
                if not _NUMBER.fullmatch(prefix):
                    raise ValueError(f"bad item: {item!r}")
                number = int(prefix)
                if not 0 <= number <= 7:
                    raise ValueError(f"value out of range: {item!r}")
                last_weekdays.add(number % 7)
                continue
            if "#" in item:
                if item.count("#") != 1:
                    raise ValueError(f"bad item: {item!r}")
                left, right = item.split("#")
                if not _NUMBER.fullmatch(left) or not _NUMBER.fullmatch(right):
                    raise ValueError(f"bad item: {item!r}")
                number, occurrence = int(left), int(right)
                if not 0 <= number <= 7:
                    raise ValueError(f"value out of range: {item!r}")
                if not 1 <= occurrence <= 5:
                    raise ValueError(f"value out of range: {item!r}")
                nth_weekdays.add((number % 7, occurrence))
                continue

        if item.count("/") > 1:
            raise ValueError(f"bad item: {item!r}")
        if "/" in item:
            base, step_text = item.split("/")
            if not _NUMBER.fullmatch(step_text):
                raise ValueError(f"bad step: {item!r}")
            step = int(step_text)
            if step < 1:
                raise ValueError(f"bad step: {item!r}")
        else:
            base, step = item, None
        if base == "":
            raise ValueError("empty item")

        if base == "*":
            sequence = list(range(low, high + 1))
        elif "-" in base:
            if base.count("-") > 1:
                raise ValueError(f"bad range: {item!r}")
            start_text, end_text = base.split("-")
            if start_text == "" or end_text == "":
                raise ValueError(f"bad range: {item!r}")
            start = _parse_value(start_text, names, low, high)
            end = _parse_value(end_text, names, low, high)
            if start <= end:
                sequence = list(range(start, end + 1))
            else:
                sequence = list(range(start, high + 1)) + list(range(low, end + 1))
        else:
            start = _parse_value(base, names, low, high)
            if step is None:
                sequence = [start]
            else:
                sequence = list(range(start, high + 1))

        if step is not None:
            sequence = sequence[::step]
        values.update(sequence)

    if kind == "dow":
        values = {value % 7 for value in values}

    return (
        tuple(sorted(values)),
        last_day,
        frozenset(last_weekdays),
        frozenset(nth_weekdays),
    )


def _parse(expr):
    if not isinstance(expr, str):
        raise ValueError(f"bad expression: {expr!r}")
    text = expr.strip()
    lowered = text.lower()
    if lowered.startswith("@"):
        if lowered not in _SHORTCUTS:
            raise ValueError(f"unknown shortcut: {expr!r}")
        text = _SHORTCUTS[lowered]

    fields = _SPLIT.split(text)
    if len(fields) != 5:
        raise ValueError(f"expected five fields: {expr!r}")

    minutes, _, _, _ = _parse_field(fields[0], "minute")
    hours, _, _, _ = _parse_field(fields[1], "hour")
    days, last_day, _, _ = _parse_field(fields[2], "dom")
    months, _, _, _ = _parse_field(fields[3], "month")
    weekdays, _, last_weekdays, nth_weekdays = _parse_field(fields[4], "dow")

    return _Schedule(
        minutes,
        hours,
        months,
        days,
        weekdays,
        last_day,
        last_weekdays,
        nth_weekdays,
    )


def _cron_weekday(date):
    return (date.weekday() + 1) % 7


def _day_allowed(schedule, date):
    last = calendar.monthrange(date.year, date.month)[1]

    day_ok = date.day in schedule.days
    if not day_ok and schedule.last_day and date.day == last:
        day_ok = True
    if not day_ok:
        return False

    weekday = _cron_weekday(date)
    if weekday in schedule.weekdays:
        return True

    if schedule.last_weekdays:
        last_weekday = _cron_weekday(dt.date(date.year, date.month, last))
        for number in schedule.last_weekdays:
            if date.day == last - ((last_weekday - number) % 7):
                return True

    if schedule.nth_weekdays:
        first_weekday = _cron_weekday(dt.date(date.year, date.month, 1))
        for number, occurrence in schedule.nth_weekdays:
            day = 1 + ((number - first_weekday) % 7) + 7 * (occurrence - 1)
            if day <= last and date.day == day:
                return True

    return False


def matches(expr, when):
    """True if the schedule expr runs at the minute of the datetime when."""
    schedule = _parse(expr)
    if when.minute not in schedule.minutes:
        return False
    if when.hour not in schedule.hours:
        return False
    if when.month not in schedule.months:
        return False
    return _day_allowed(schedule, when.date())


def next_run(expr, after):
    """The first run of expr strictly after the datetime after, or None."""
    schedule = _parse(expr)

